let currentLang = (() => { try { return localStorage.getItem('saludplus_language_v13') === 'en' ? 'en' : 'es'; } catch (e) { return 'es'; } })();
function t(es) { return currentLang === 'en' && Object.prototype.hasOwnProperty.call(EN, es) ? EN[es] : es; }

function applyLanguage(lang) {
  currentLang = lang === 'en' ? 'en' : 'es';
  try { localStorage.setItem('saludplus_language_v13', currentLang); } catch (e) { /* sin almacenamiento */ }
  document.documentElement.lang = currentLang;
  document.querySelectorAll('[data-lang]').forEach(b => b.classList.toggle('on', b.dataset.lang === currentLang));
  document.querySelectorAll('[data-i18n]').forEach(el => {
    if (el.dataset.es === undefined) el.dataset.es = el.textContent.trim();
    const v = t(el.dataset.es); if (el.textContent !== v) el.textContent = v;
  });
  document.querySelectorAll('option').forEach(el => {
    if (el.dataset.es === undefined) el.dataset.es = el.textContent.trim();
    const v = t(el.dataset.es); if (el.textContent !== v) el.textContent = v;
  });
  document.querySelectorAll('[placeholder]').forEach(el => {
    if (el.dataset.esPh === undefined) el.dataset.esPh = el.getAttribute('placeholder');
    el.setAttribute('placeholder', t(el.dataset.esPh));
  });
}
